from collections import defaultdict
def transform(g):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    hlines=[]; hcells=set()
    for i,row in enumerate(g):
        byc=defaultdict(list)
        for j,v in enumerate(row):
            if v: byc[v].append(j)
        for c,js in byc.items():
            if len(js)>=2:
                hlines.append((i,c,min(js),max(js)))
                hcells|={(i,j) for j in js}
    for i,c,a,b in hlines:
        for j in range(a,b+1): out[i][j]=c
    for j in range(w):
        byc=defaultdict(list)
        for i in range(h):
            v=g[i][j]
            if v and (i,j) not in hcells: byc[v].append(i)
